#!/usr/bin/env sh

rm -rf "../web_assets/assets"

yarn && yarn build


original_file="../web_assets/index.html"
output_file="tmp"

sed 's|src="/assets|src="/web_assets/assets|g; s|href="/assets|href="/web_assets/assets|g' "$original_file" > "$output_file"

mv $output_file $original_filedescribe('hotrod demo spec', () => {
  it('request ride and check deliver',
    () => {
      // request a ride
      cy.requestRide('1', '123')

      // check if the driver has been delivered
      cy.get(':nth-child(6) > .css-bjcoli').contains(/Driver (.*) arriving in (.*)./);
    });
})import { test, expect } from "@playwright/test";

test.describe("Request a ride", () => {
	test("check route resolve routes", async ({ page }) => {
		await page.goto("/");
		await page.waitForLoadState();

		await page.getByRole("combobox").first().selectOption("1");
		await page.getByRole("combobox").nth(1).selectOption("123");
		await page.getByRole("button", { name: "Request Ride" }).click();

		await expect(
			page.locator("//div[p[2][contains(text(), 'route')]]/p[4]"),
		).toHaveText("Resolving routes")
	});

	test("check driver series", async ({ page }) => {
		await page.goto("/");
		await page.waitForLoadState();

		await page.getByRole("combobox").first().selectOption("1");
		await page.getByRole("combobox").nth(1).selectOption("123");
		await page.getByRole("button", { name: "Request Ride" }).click();

		await expect(
			page.locator("//div[p[2][contains(text(), 'driver')]]/p[4]").last(),
		).toHaveText(/.*T7\d{5}C.*/);
	});
});
